(function(){
  window.UP = window.UP || {};
  UP.science10Q = [{"id":"sci10-01-q01","cls":10,"subject":"science","board":"cbse","ans":"(a) and (b)","qno":1,"ansLetter":"A","opts":[{"en":"(a) and (b)","hi":""},{"en":"(a) and (c)","hi":""},{"en":"(a), (b) and (c)","hi":""},{"en":"all","hi":""}],"ch":1,"chapter":"Chemical Reactions and Equations","en":"Which of the statements about the reaction below are incorrect? 2PbO(s) + C(s) → 2Pb(s) + CO2(g) (a) Lead is getting reduced. (b) Carbon dioxide is getting oxidised. (c) Carbon is getting oxidised. (d) Lead oxide is getting reduced.","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-01-q02","cls":10,"subject":"science","board":"cbse","ans":"displacement reaction.","qno":2,"ansLetter":"D","opts":[{"en":"combination reaction.","hi":""},{"en":"double displacement reaction.","hi":""},{"en":"decomposition reaction.","hi":""},{"en":"displacement reaction.","hi":""}],"ch":1,"chapter":"Chemical Reactions and Equations","en":"Fe₂O₃ + 2Al → Al₂O₃ + 2Fe\nThe above reaction is an example of a","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-01-q03","cls":10,"subject":"science","board":"cbse","ans":"Hydrogen gas and iron chloride are produced.","qno":3,"ansLetter":"A","opts":[{"en":"Hydrogen gas and iron chloride are produced.","hi":""},{"en":"Chlorine gas and iron hydroxide are produced.","hi":""},{"en":"No reaction takes place.","hi":""},{"en":"Iron salt and water are produced.","hi":""}],"ch":1,"chapter":"Chemical Reactions and Equations","en":"What happens when dilute hydrochloric acid is added to iron filings? Choose the correct answer.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-01-q04","cls":10,"subject":"science","board":"cbse","ans":"A balanced chemical equation has an equal number of atoms of each element on both the reactant and product sides (e.g., 2H₂ + O₂ → 2H₂O). Chemical equations must be balanced to satisfy the Law of Conservation of Mass — mass (atoms) can neither be created nor destroyed in a chemical reaction.","qno":4,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"What is a balanced chemical equation? Why should chemical equations be balanced?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q05","cls":10,"subject":"science","board":"cbse","ans":"(a) 3H₂(g) + N₂(g) → 2NH₃(g)\n(b) 2H₂S(g) + 3O₂(g) → 2H₂O(l) + 2SO₂(g)\n(c) 3BaCl₂(aq) + Al₂(SO₄)₃(aq) → 2AlCl₃(aq) + 3BaSO₄(s)↓\n(d) 2K(s) + 2H₂O(l) → 2KOH(aq) + H₂(g)↑","qno":5,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Translate the following statements into chemical equations and then balance them:\n(a) Hydrogen gas combines with nitrogen to form ammonia.\n(b) Hydrogen sulphide gas burns in air to give water and sulphur dioxide.\n(c) Barium chloride reacts with aluminium sulphate to give aluminium chloride and a precipitate of barium sulphate.\n(d) Potassium metal reacts with water to give potassium hydroxide and hydrogen gas.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q06","cls":10,"subject":"science","board":"cbse","ans":"(a) 2HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + 2H₂O\n(b) 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O\n(c) NaCl + AgNO₃ → AgCl + NaNO₃ (already balanced)\n(d) BaCl₂ + H₂SO₄ → BaSO₄ + 2HCl","qno":6,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Balance the following chemical equations:\n(a) HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + H₂O\n(b) NaOH + H₂SO₄ → Na₂SO₄ + H₂O\n(c) NaCl + AgNO₃ → AgCl + NaNO₃\n(d) BaCl₂ + H₂SO₄ → BaSO₄ + HCl","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q07","cls":10,"subject":"science","board":"cbse","ans":"(a) Ca(OH)₂(aq) + CO₂(g) → CaCO₃(s) + H₂O(l)\n(b) Zn(s) + 2AgNO₃(aq) → Zn(NO₃)₂(aq) + 2Ag(s)\n(c) 2Al(s) + 3CuCl₂(aq) → 2AlCl₃(aq) + 3Cu(s)\n(d) BaCl₂(aq) + K₂SO₄(aq) → BaSO₄(s)↓ + 2KCl(aq)","qno":7,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Write the balanced chemical equations for the following reactions:\n(a) Calcium hydroxide + Carbon dioxide → Calcium carbonate + Water\n(b) Zinc + Silver nitrate → Zinc nitrate + Silver\n(c) Aluminium + Copper chloride → Aluminium chloride + Copper\n(d) Barium chloride + Potassium sulphate → Barium sulphate + Potassium chloride","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q08","cls":10,"subject":"science","board":"cbse","ans":"(a) 2KBr(aq) + BaI₂(aq) → 2KI(aq) + BaBr₂(s) — Double displacement (precipitation) reaction.\n(b) ZnCO₃(s) → ZnO(s) + CO₂(g) — Thermal decomposition reaction.\n(c) H₂(g) + Cl₂(g) → 2HCl(g) — Combination reaction.\n(d) Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g) — Displacement reaction.","qno":8,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Write the balanced chemical equation for the following and identify the type of reaction in each case:\n(a) Potassium bromide(aq) + Barium iodide(aq) → Potassium iodide(aq) + Barium bromide(s)\n(b) Zinc carbonate(s) → Zinc oxide(s) + Carbon dioxide(g)\n(c) Hydrogen(g) + Chlorine(g) → Hydrogen chloride(g)\n(d) Magnesium(s) + Hydrochloric acid(aq) → Magnesium chloride(aq) + Hydrogen(g)","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q09","cls":10,"subject":"science","board":"cbse","ans":"Exothermic reactions release heat along with the formation of products — e.g., burning of natural gas: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(g) + Heat; respiration. Endothermic reactions absorb energy (heat, light or electricity) from the surroundings — e.g., CaCO₃(s) + Heat → CaO(s) + CO₂(g); N₂(g) + O₂(g) + Heat → 2NO(g).","qno":9,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"What does one mean by exothermic and endothermic reactions? Give examples.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q10","cls":10,"subject":"science","board":"cbse","ans":"During digestion, carbohydrates are broken down into glucose. In cells, glucose combines with oxygen to form carbon dioxide and water while releasing energy (ATP + heat): C₆H₁₂O₆(aq) + 6O₂(aq) → 6CO₂(aq) + 6H₂O(l) + Energy. Since energy is released, respiration is an exothermic reaction.","qno":10,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Why is respiration considered an exothermic reaction? Explain.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q11","cls":10,"subject":"science","board":"cbse","ans":"In a combination reaction, two or more substances combine to form a single product (e.g., 2H₂(g) + O₂(g) → 2H₂O(l)), whereas in a decomposition reaction, a single compound breaks down into two or more simpler substances using energy (e.g., 2H₂O(l) --(electricity)--> 2H₂(g) + O₂(g)). Hence they are opposites.","qno":11,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Why are decomposition reactions called the opposite of combination reactions? Write equations for these reactions.","kind":"long","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q12","cls":10,"subject":"science","board":"cbse","ans":"• By heat (thermolysis): CaCO₃(s) --(Heat)--> CaO(s) + CO₂(g)\n• By light (photolysis): 2AgCl(s) --(Sunlight)--> 2Ag(s) + Cl₂(g)\n• By electricity (electrolysis): 2H₂O(l) --(Electric current)--> 2H₂(g) + O₂(g)","qno":12,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Write one equation each for decomposition reactions where energy is supplied in the form of heat, light or electricity.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q13","cls":10,"subject":"science","board":"cbse","ans":"In a displacement reaction, a more reactive element displaces a less reactive element from its salt solution: Zn(s) + CuSO₄(aq) → ZnSO₄(aq) + Cu(s). In a double displacement reaction, two compounds exchange ions in solution to form new compounds (often a precipitate): Na₂SO₄(aq) + BaCl₂(aq) → BaSO₄(s)↓ + 2NaCl(aq).","qno":13,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"What is the difference between displacement and double displacement reactions? Write equations for these reactions.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":13,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q14","cls":10,"subject":"science","board":"cbse","ans":"Cu(s) + 2AgNO₃(aq) → Cu(NO₃)₂(aq) + 2Ag(s). Copper, being more reactive than silver, displaces silver metal from silver nitrate solution.","qno":14,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"In the refining of silver, the recovery of silver from silver nitrate solution involved displacement by copper metal. Write down the reaction involved.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":14,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q15","cls":10,"subject":"science","board":"cbse","ans":"Any reaction that produces an insoluble solid (precipitate) which separates out from the solution is called a precipitation reaction. Examples: (1) Na₂SO₄(aq) + BaCl₂(aq) → BaSO₄(s)↓ (white ppt.) + 2NaCl(aq); (2) AgNO₃(aq) + NaCl(aq) → AgCl(s)↓ (white ppt.) + NaNO₃(aq).","qno":15,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"What do you mean by a precipitation reaction? Explain by giving examples.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":15,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q16","cls":10,"subject":"science","board":"cbse","ans":"(a) Oxidation is the gain of oxygen by a substance. Examples: (1) 2Cu + O₂ --(Heat)--> 2CuO (copper oxidised to CuO); (2) C + O₂ → CO₂ (carbon oxidised to CO₂).\n(b) Reduction is the loss of oxygen from a substance. Examples: (1) CuO + H₂ --(Heat)--> Cu + H₂O (CuO reduced to Cu); (2) ZnO + C → Zn + CO (ZnO reduced to Zn).","qno":16,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Explain the following in terms of gain or loss of oxygen with two examples each:\n(a) Oxidation\n(b) Reduction","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":16,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q17","cls":10,"subject":"science","board":"cbse","ans":"Element ‘X’ is Copper (Cu). On heating in air it forms black Copper(II) oxide (CuO): 2Cu(s) + O₂(g) --(Heat)--> 2CuO(s).","qno":17,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"A shiny brown coloured element ‘X’ on heating in air becomes black in colour. Name the element ‘X’ and the black coloured compound formed.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":17,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q18","cls":10,"subject":"science","board":"cbse","ans":"Paint forms a protective coating on the surface of iron and cuts off direct contact with air (oxygen) and moisture, thereby preventing rusting (corrosion) of iron.","qno":18,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Why do we apply paint on iron articles?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":18,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q19","cls":10,"subject":"science","board":"cbse","ans":"Oils and fats get oxidised in contact with oxygen and become rancid (foul smell and taste). Flushing packets with unreactive nitrogen gas displaces oxygen and acts as an antioxidant, preventing rancidity.","qno":19,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Oil and fat containing food items are flushed with nitrogen. Why?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":19,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-01-q20","cls":10,"subject":"science","board":"cbse","ans":"(a) Corrosion: Slow deterioration of metals when attacked by air, moisture or acids around them. Example: Rusting of iron (formation of reddish-brown hydrated ferric oxide, Fe₂O₃·xH₂O), or black coating of Ag₂S on silver.\n(b) Rancidity: Oxidation of fats and oils in food when left exposed to air, causing unpleasant smell and taste. Example: Potato chips or butter turning stale and foul-smelling when kept open.","qno":20,"ansLetter":null,"opts":null,"ch":1,"chapter":"Chemical Reactions and Equations","en":"Explain the following terms with one example each:\n(a) Corrosion\n(b) Rancidity","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 1, Exercise","fig":null,"q":20,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q01","cls":10,"subject":"science","board":"cbse","ans":"10","qno":1,"ansLetter":"D","opts":[{"en":"1","hi":""},{"en":"4","hi":""},{"en":"5","hi":""},{"en":"10","hi":""}],"ch":2,"chapter":"Acids, Bases and Salts","en":"A solution turns red litmus blue, its pH is likely to be","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-02-q02","cls":10,"subject":"science","board":"cbse","ans":"HCl","qno":2,"ansLetter":"B","opts":[{"en":"NaCl","hi":""},{"en":"HCl","hi":""},{"en":"LiCl","hi":""},{"en":"KCl","hi":""}],"ch":2,"chapter":"Acids, Bases and Salts","en":"A solution reacts with crushed egg-shells to give a gas that turns lime-water milky. The solution contains","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-02-q03","cls":10,"subject":"science","board":"cbse","ans":"16 mL","qno":3,"ansLetter":"D","opts":[{"en":"4 mL","hi":""},{"en":"8 mL","hi":""},{"en":"12 mL","hi":""},{"en":"16 mL","hi":""}],"ch":2,"chapter":"Acids, Bases and Salts","en":"10 mL of a solution of NaOH is found to be completely neutralised by 8 mL of a given solution of HCl. If we take 20 mL of the same solution of NaOH, the amount of HCl solution (the same solution as before) required to neutralise it will be","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-02-q04","cls":10,"subject":"science","board":"cbse","ans":"Antacid","qno":4,"ansLetter":"C","opts":[{"en":"Antibiotic","hi":""},{"en":"Analgesic","hi":""},{"en":"Antacid","hi":""},{"en":"Antiseptic","hi":""}],"ch":2,"chapter":"Acids, Bases and Salts","en":"Which one of the following types of medicines is used for treating indigestion?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-02-q05","cls":10,"subject":"science","board":"cbse","ans":"(a) Dilute sulphuric acid + Zinc → Zinc sulphate + Hydrogen; H₂SO₄(aq) + Zn(s) → ZnSO₄(aq) + H₂(g)\n(b) Dilute hydrochloric acid + Magnesium → Magnesium chloride + Hydrogen; 2HCl(aq) + Mg(s) → MgCl₂(aq) + H₂(g)\n(c) Dilute sulphuric acid + Aluminium → Aluminium sulphate + Hydrogen; 3H₂SO₄(aq) + 2Al(s) → Al₂(SO₄)₃(aq) + 3H₂(g)\n(d) Dilute hydrochloric acid + Iron → Iron(II) chloride + Hydrogen; 2HCl(aq) + Fe(s) → FeCl₂(aq) + H₂(g)","qno":5,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Write word equations and then balanced equations for the reaction taking place when:\n(a) dilute sulphuric acid reacts with zinc granules.\n(b) dilute hydrochloric acid reacts with magnesium ribbon.\n(c) dilute sulphuric acid reacts with aluminium powder.\n(d) dilute hydrochloric acid reacts with iron filings.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q06","cls":10,"subject":"science","board":"cbse","ans":"Fix two iron nails on a cork in a beaker and connect them to a 6 V battery through a bulb and switch. Pour dilute HCl — the bulb glows because HCl ionises to give H⁺(aq) ions. Repeat separately with glucose and alcohol solutions — the bulb does NOT glow because glucose and ethanol do not dissociate into H⁺ ions in water, proving they are not acids.","qno":6,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Compounds such as alcohols and glucose also contain hydrogen but are not categorised as acids. Describe an Activity to prove it.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q07","cls":10,"subject":"science","board":"cbse","ans":"Distilled water is pure and contains no dissolved ionic salts or free ions to carry charge. Rainwater dissolves atmospheric gases like CO₂ (forming carbonic acid, H₂CO₃) and traces of SO₂/NO₂, producing free H⁺ and anion charge carriers that conduct electricity.","qno":7,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Why does distilled water not conduct electricity, whereas rain water does?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q08","cls":10,"subject":"science","board":"cbse","ans":"Acidic behaviour is due to hydrogen/hydronium ions (H⁺(aq) or H₃O⁺). Separation of H⁺ ions from acid molecules (like HCl) cannot occur without water molecules (HCl + H₂O → H₃O⁺ + Cl⁻); hence dry acids do not show acidic properties.","qno":8,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Why do acids not show acidic behaviour in the absence of water?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q09","cls":10,"subject":"science","board":"cbse","ans":"(a) Neutral: D (pH 7)\n(b) Strongly alkaline: C (pH 11)\n(c) Strongly acidic: B (pH 1)\n(d) Weakly acidic: A (pH 4)\n(e) Weakly alkaline: E (pH 9)\nIncreasing order of H⁺ ion concentration (decreasing pH): C (11) < E (9) < D (7) < A (4) < B (1).","qno":9,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Five solutions A, B, C, D and E when tested with universal indicator showed pH as 4, 1, 11, 7 and 9, respectively. Which solution is:\n(a) neutral?\n(b) strongly alkaline?\n(c) strongly acidic?\n(d) weakly acidic?\n(e) weakly alkaline?\nArrange the pH in increasing order of hydrogen-ion concentration.","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q10","cls":10,"subject":"science","board":"cbse","ans":"Fizzing (evolution of H₂ gas) will occur more vigorously in test tube A (containing HCl). HCl is a strong acid that dissociates completely in water giving a much higher concentration of H⁺ ions than acetic acid (CH₃COOH), which is a weak acid and only partially ionised.","qno":10,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Equal lengths of magnesium ribbons are taken in test tubes A and B. Hydrochloric acid (HCl) is added to test tube A, while acetic acid (CH₃COOH) is added to test tube B. Amount and concentration taken for both the acids are same. In which test tube will the fizzing occur more vigorously and why?","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q11","cls":10,"subject":"science","board":"cbse","ans":"The pH will decrease below 6 (become more acidic). As milk sets into curd, Lactobacillus bacteria convert lactose sugar into lactic acid, increasing H⁺ ion concentration and lowering pH.","qno":11,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Fresh milk has a pH of 6. How do you think the pH will change as it turns into curd? Explain your answer.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q12","cls":10,"subject":"science","board":"cbse","ans":"(a) Making fresh milk slightly alkaline (using mild base NaHCO₃) prevents it from turning sour/spoiling quickly due to lactic acid formation.\n(b) It takes longer to set as curd because the lactic acid produced initially by bacteria is first used up in neutralising the added baking soda before the pH can drop enough to coagulate milk.","qno":12,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"A milkman adds a very small amount of baking soda to fresh milk.\n(a) Why does he shift the pH of the fresh milk from 6 to slightly alkaline?\n(b) Why does this milk take a long time to set as curd?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q13","cls":10,"subject":"science","board":"cbse","ans":"Plaster of Paris (CaSO₄·½H₂O) readily absorbs moisture from air and hydrates into hard solid gypsum, losing its setting property: CaSO₄·½H₂O + 1½H₂O → CaSO₄·2H₂O (Gypsum). Therefore it must be stored in a moisture-proof container.","qno":13,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Plaster of Paris should be stored in a moisture-proof container. Explain why?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":13,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q14","cls":10,"subject":"science","board":"cbse","ans":"The reaction between an acid and a base to form salt and water is called a neutralisation reaction (H⁺(aq) + OH⁻(aq) → H₂O(l)). Examples: (1) NaOH(aq) + HCl(aq) → NaCl(aq) + H₂O(l); (2) KOH(aq) + HNO₃(aq) → KNO₃(aq) + H₂O(l).","qno":14,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"What is a neutralisation reaction? Give two examples.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":null,"q":14,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-02-q15","cls":10,"subject":"science","board":"cbse","ans":"Uses of washing soda (Na₂CO₃·10H₂O): (1) Used in glass, soap and paper industries; (2) Used for removing permanent hardness of water (and as a domestic cleaning agent).\nUses of baking soda (NaHCO₃): (1) Used in making baking powder (for spongy cakes/bread) and as an antacid to relieve acidity; (2) Used in soda-acid fire extinguishers.","qno":15,"ansLetter":null,"opts":null,"ch":2,"chapter":"Acids, Bases and Salts","en":"Give two important uses of washing soda and baking soda.","kind":"long","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 2, Exercise","fig":{"id":"c02-f2_10","num":"2.10","cap":"(a) Ignition tube containing dilute sulphuric acid suspended in a wash-bottle containing","src":"assets/science/figs/c02-f2_10.png"},"q":15,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q01","cls":10,"subject":"science","board":"cbse","ans":"AgNO3 solution and copper metal.","qno":1,"ansLetter":"D","opts":[{"en":"NaCl solution and copper metal","hi":""},{"en":"MgCl2 solution and aluminium metal","hi":""},{"en":"FeSO4 solution and silver metal","hi":""},{"en":"AgNO3 solution and copper metal.","hi":""}],"ch":3,"chapter":"Metals and Non-metals","en":"Which of the following pairs will give displacement reactions?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-03-q02","cls":10,"subject":"science","board":"cbse","ans":"Applying a coating of zinc","qno":2,"ansLetter":"C","opts":[{"en":"Applying grease","hi":""},{"en":"Applying paint","hi":""},{"en":"Applying a coating of zinc","hi":""},{"en":"All of the above.","hi":""}],"ch":3,"chapter":"Metals and Non-metals","en":"Which of the following methods is suitable for preventing an iron frying pan from rusting?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-03-q03","cls":10,"subject":"science","board":"cbse","ans":"calcium","qno":3,"ansLetter":"A","opts":[{"en":"calcium","hi":""},{"en":"carbon","hi":""},{"en":"silicon","hi":""},{"en":"iron.","hi":""}],"ch":3,"chapter":"Metals and Non-metals","en":"An element reacts with oxygen to give a compound with a high melting point. This compound is also soluble in water. The element is likely to be","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-03-q04","cls":10,"subject":"science","board":"cbse","ans":"zinc is more reactive than tin.","qno":4,"ansLetter":"C","opts":[{"en":"zinc is costlier than tin.","hi":""},{"en":"zinc has a higher melting point than tin.","hi":""},{"en":"zinc is more reactive than tin.","hi":""},{"en":"zinc is less reactive than tin.","hi":""}],"ch":3,"chapter":"Metals and Non-metals","en":"Food cans are coated with tin and not with zinc because","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-03-q05","cls":10,"subject":"science","board":"cbse","ans":"(a) (i) Hammer test: Strike each sample — metals flatten into thin sheets (malleable) without breaking, whereas non-metals break into pieces (brittle). (ii) Electrical circuit test: Connect each sample between battery, bulb and switch — the bulb glows with metals (good conductors) and generally does not glow with non-metals.\n(b) These physical tests are quick and useful, though exceptions exist (e.g., graphite is a non-metal that conducts electricity; sodium/potassium are soft metals).","qno":5,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"You are given a hammer, a battery, a bulb, wires and a switch.\n(a) How could you use them to distinguish between samples of metals and non-metals?\n(b) Assess the usefulness of these tests in distinguishing between metals and non-metals.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q06","cls":10,"subject":"science","board":"cbse","ans":"Metal oxides which react with both acids and bases to produce salt and water are called amphoteric oxides. Examples: Aluminium oxide (Al₂O₃) and Zinc oxide (ZnO). For Al₂O₃: Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O; Al₂O₃ + 2NaOH → 2NaAlO₂ + H₂O.","qno":6,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"What are amphoteric oxides? Give two examples of amphoteric oxides.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q07","cls":10,"subject":"science","board":"cbse","ans":"Metals that displace hydrogen from dilute acids (above H in reactivity series): Zinc (Zn) and Magnesium (Mg) [also Fe, Al].\nMetals that do NOT displace hydrogen from dilute acids (below H): Copper (Cu) and Silver (Ag) [also Au, Hg].","qno":7,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"Name two metals which will displace hydrogen from dilute acids, and two metals which will not.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q08","cls":10,"subject":"science","board":"cbse","ans":"• Anode: A thick block/rod of impure metal M.\n• Cathode: A thin strip of pure metal M.\n• Electrolyte: An acidified aqueous solution of a water-soluble salt of metal M (e.g., acidified CuSO₄ solution for refining copper).","qno":8,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"In the electrolytic refining of a metal M, what would you take as the anode, the cathode and the electrolyte?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q09","cls":10,"subject":"science","board":"cbse","ans":"(a) Sulphur burns in air to form sulphur dioxide (SO₂) gas: (i) No action on dry litmus paper (no H⁺ ions without water); (ii) Turns moist blue litmus paper red because SO₂ dissolves in water to form sulphurous acid (H₂SO₃).\n(b) S(s) + O₂(g) → SO₂(g); and SO₂(g) + H₂O(l) → H₂SO₃(aq).","qno":9,"q":9,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"Pratyush took sulphur powder on a spatula and heated it. He collected the gas evolved by inverting a test tube over it.\n(a) What will be the action of gas on (i) dry litmus paper? (ii) moist litmus paper?\n(b) Write a balanced chemical equation for the reaction taking place.","hi":"","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Ch 3 Exercise Q9","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q10","cls":10,"subject":"science","board":"cbse","ans":"Two ways to prevent rusting of iron: (1) Galvanisation — coating iron articles with a thin layer of zinc; (2) Painting, oiling, greasing, chrome plating or alloying (making stainless steel) to prevent contact with air and moisture.","qno":10,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"State two ways to prevent the rusting of iron.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q11","cls":10,"subject":"science","board":"cbse","ans":"Non-metals combine with oxygen to form acidic oxides (e.g., CO₂, SO₂, NO₂) or neutral oxides (e.g., CO, H₂O, N₂O).","qno":11,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"What type of oxides are formed when non-metals combine with oxygen?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q12","cls":10,"subject":"science","board":"cbse","ans":"(a) Platinum, gold and silver are very lustrous, highly malleable and ductile, and least reactive — they do not corrode or tarnish easily.\n(b) Sodium, potassium and lithium are extremely reactive; they react vigorously with oxygen and moisture in air and catch fire, so they are stored under kerosene/paraffin oil.\n(c) Aluminium forms a tough, thin, non-porous protective layer of aluminium oxide (Al₂O₃) that prevents further corrosion, and it is a good conductor of heat.\n(d) It is much easier to obtain a metal by reducing its oxide than directly from its carbonate or sulphide; hence carbonates (by calcination) and sulphides (by roasting) are first converted to oxides.","qno":12,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"Give reasons:\n(a) Platinum, gold and silver are used to make jewellery.\n(b) Sodium, potassium and lithium are stored under oil.\n(c) Aluminium is a highly reactive metal, yet it is used to make utensils for cooking.\n(d) Carbonate and sulphide ores are usually converted into oxides during the process of extraction.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q13","cls":10,"subject":"science","board":"cbse","ans":"Copper reacts slowly with moist CO₂ in air to form a dull green coating of basic copper carbonate (CuCO₃·Cu(OH)₂). Lemon and tamarind juice contain acids (citric/tartaric acid) which neutralise and dissolve this basic layer, restoring copper’s shine, while not reacting with copper metal itself.","qno":13,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"You must have seen tarnished copper vessels being cleaned with lemon or tamarind juice. Explain why these sour substances are effective in cleaning the vessels.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":13,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q14","cls":10,"subject":"science","board":"cbse","ans":"1. Metals form basic or amphoteric oxides (e.g., Na₂O, Al₂O₃); non-metals form acidic or neutral oxides (e.g., CO₂, CO).\n2. Reactive metals displace H₂ from dilute acids and water; non-metals do not displace H₂ from dilute acids.\n3. Metals are electropositive (lose electrons to form cations, acting as reducing agents); non-metals are electronegative (gain/share electrons, acting as oxidising agents).","qno":14,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"Differentiate between metal and non-metal on the basis of their chemical properties.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":14,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q15","cls":10,"subject":"science","board":"cbse","ans":"He used Aqua Regia — a freshly prepared 3:1 mixture of concentrated hydrochloric acid (HCl) and concentrated nitric acid (HNO₃). Though neither acid alone dissolves gold, aqua regia is highly corrosive and dissolves the outer layer of gold, exposing a shiny inner surface while reducing the bangles’ weight.","qno":15,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"A man went door to door posing as a goldsmith. He promised to bring back the glitter of old and dull gold ornaments. An unsuspecting lady gave a set of gold bangles to him which he dipped in a particular solution. The bangles sparkled like new but their weight was reduced drastically. The lady was upset but after a futile argument the man beat a hasty retreat. Can you play the detective to find out the nature of the solution he had used?","kind":"long","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":15,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-03-q16","cls":10,"subject":"science","board":"cbse","ans":"Copper does not react with cold water, hot water or steam, and is an excellent conductor of heat. Steel contains iron, which reacts with steam formed from hot water (3Fe + 4H₂O(g) → Fe₃O₄ + 4H₂) and corrodes over time. Hence copper is preferred.","qno":16,"ansLetter":null,"opts":null,"ch":3,"chapter":"Metals and Non-metals","en":"Give reasons why copper is used to make hot water tanks and not steel (an alloy of iron).","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 3, Exercise","fig":null,"q":16,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q01","cls":10,"subject":"science","board":"cbse","ans":"7 covalent bonds.","qno":1,"ansLetter":"B","opts":[{"en":"6 covalent bonds.","hi":""},{"en":"7 covalent bonds.","hi":""},{"en":"8 covalent bonds.","hi":""},{"en":"9 covalent bonds.","hi":""}],"ch":4,"chapter":"Carbon and its Compounds","en":"Ethane, with the molecular formula C₂H₆ has","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 4, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-04-q02","cls":10,"subject":"science","board":"cbse","ans":"ketone.","qno":2,"ansLetter":"C","opts":[{"en":"carboxylic acid.","hi":""},{"en":"aldehyde.","hi":""},{"en":"ketone.","hi":""},{"en":"alcohol.","hi":""}],"ch":4,"chapter":"Carbon and its Compounds","en":"Butanone is a four-carbon compound with the functional group","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 4, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-04-q03","cls":10,"subject":"science","board":"cbse","ans":"the fuel is not burning completely.","qno":3,"ansLetter":"B","opts":[{"en":"the food is not cooked completely.","hi":""},{"en":"the fuel is not burning completely.","hi":""},{"en":"the fuel is wet.","hi":""},{"en":"the fuel is burning completely.","hi":""}],"ch":4,"chapter":"Carbon and its Compounds","en":"While cooking, if the bottom of the vessel is getting blackened on the outside, it means that","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 4, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-04-q04","cls":10,"subject":"science","board":"cbse","ans":"Carbon (atomic no. 6; 2,4) needs 4 electrons to complete its octet; each H (1) needs 1 electron for its duplet; Cl (2,8,7) needs 1 electron for its octet. Carbon shares three valence electrons with three H atoms (three C–H single covalent bonds) and its fourth valence electron with one Cl atom (one C–Cl single covalent bond), forming covalent CH₃Cl in which every atom attains a noble-gas configuration.","qno":4,"q":4,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Explain the nature of the covalent bond using the bond formation in CH₃Cl.","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q4","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q05","cls":10,"subject":"science","board":"cbse","ans":"(a) Ethanoic acid (CH₃COOH): Methyl carbon forms 3 single bonds with H and 1 single bond with carboxyl carbon; carboxyl carbon forms a double bond (=O, 2 shared pairs) with one O (having 2 lone pairs) and a single bond with –OH oxygen (having 2 lone pairs and 1 single bond to H).\n(b) H₂S: Sulphur (6 valence e⁻) shares 1 electron pair with each of two H atoms (H–S–H) and retains 2 lone pairs.\n(c) Propanone (CH₃COCH₃): Central carbonyl carbon forms single bonds to two –CH₃ groups and a double bond (2 shared pairs) to oxygen (2 lone pairs).\n(d) F₂: Each F atom (7 valence e⁻) shares 1 electron pair to form F–F, with 3 lone pairs on each F atom.","qno":5,"q":5,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Draw the electron dot structures for:\n(a) ethanoic acid\n(b) H₂S\n(c) propanone\n(d) F₂","hi":"","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q5","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q06","cls":10,"subject":"science","board":"cbse","ans":"A homologous series is a family of organic compounds having the same functional group and similar chemical properties in which successive members differ by a –CH₂– unit (14 u molecular mass) and show a regular gradation in physical properties. Example: Alkanes (CₙH₂ₙ₊₂) — CH₄, C₂H₆, C₃H₈, C₄H₁₀; or Alcohols — CH₃OH, C₂H₅OH, C₃H₇OH.","qno":6,"q":6,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"What is a homologous series? Explain with an example.","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q6","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q07","cls":10,"subject":"science","board":"cbse","ans":"Physical properties: (1) Ethanol has a pleasant smell and burning taste, whereas ethanoic acid has a pungent vinegar-like smell and sour taste; (2) Melting point of ethanol is 156 K vs 290 K for ethanoic acid (which freezes in winter as glacial acetic acid).\nChemical properties: (1) Ethanoic acid turns blue litmus red; ethanol is neutral to litmus. (2) Ethanoic acid reacts with NaHCO₃/Na₂CO₃ giving brisk effervescence of CO₂ gas (CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂↑), whereas ethanol does not react.","qno":7,"q":7,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"How can ethanol and ethanoic acid be differentiated on the basis of their physical and chemical properties?","hi":"","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q7","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q08","cls":10,"subject":"science","board":"cbse","ans":"A soap molecule has two ends: a hydrophilic (water-loving) ionic head (–COO⁻Na⁺) and a hydrophobic (water-repelling) long hydrocarbon tail. In water, hydrophobic tails cluster inward away from water while ionic heads point outward into water, forming spherical micelles. Micelles will NOT form in ethanol because the hydrocarbon tail is soluble in ethanol.","qno":8,"q":8,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Why does micelle formation take place when soap is added to water? Will a micelle be formed in other solvents such as ethanol also?","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q8","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q09","cls":10,"subject":"science","board":"cbse","ans":"Carbon and its compounds undergo combustion in oxygen to form CO₂ and H₂O while releasing a large amount of heat and light energy (high calorific value), have moderate ignition temperatures, burn cleanly when supplied sufficient oxygen, and their combustion is easy to control.","qno":9,"q":9,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Why are carbon and its compounds used as fuels for most applications?","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q9","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q10","cls":10,"subject":"science","board":"cbse","ans":"Hard water contains dissolved calcium (Ca²⁺) and magnesium (Mg²⁺) salts. Soap (sodium/potassium salt of long-chain fatty acids, e.g., C₁₇H₃₅COONa) reacts with Ca²⁺ and Mg²⁺ ions to form insoluble curdy white precipitates of calcium and magnesium salts of fatty acids called scum: 2C₁₇H₃₅COONa + Ca²⁺ → (C₁₇H₃₅COO)₂Ca↓ (scum) + 2Na⁺.","qno":10,"q":10,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Explain the formation of scum when hard water is treated with soap.","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q10","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q11","cls":10,"subject":"science","board":"cbse","ans":"Soap solution is basic (alkaline) in nature (salt of a weak fatty acid and strong base NaOH/KOH). Hence it turns red litmus paper blue and leaves blue litmus paper unchanged.","qno":11,"q":11,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"What change will you observe if you test soap with litmus paper (red and blue)?","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q11","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q12","cls":10,"subject":"science","board":"cbse","ans":"Hydrogenation is the addition of hydrogen (H₂) to unsaturated hydrocarbons in the presence of catalysts such as nickel (Ni) or palladium (Pd) to form saturated hydrocarbons. Industrial application: Conversion of liquid unsaturated vegetable oils into solid saturated fats (vanaspati ghee) using a nickel catalyst.","qno":12,"q":12,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"What is hydrogenation? What is its industrial application?","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q12","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q13","cls":10,"subject":"science","board":"cbse","ans":"C₃H₆ (propene, an alkene CₙH₂ₙ) and C₂H₂ (ethyne, an alkyne CₙH₂ₙ₋₂) undergo addition reactions because they are unsaturated hydrocarbons containing double/triple carbon-carbon bonds. C₂H₆, C₃H₈ and CH₄ are saturated alkanes.","qno":13,"q":13,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Which of the following hydrocarbons undergo addition reactions: C₂H₆, C₃H₈, C₃H₆, C₂H₂ and CH₄?","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q13","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q14","cls":10,"subject":"science","board":"cbse","ans":"(1) Bromine water test: Unsaturated hydrocarbons decolourise reddish-brown bromine water by addition, whereas saturated hydrocarbons do not.\n(2) Flame test: Saturated hydrocarbons generally burn with a clean blue flame, while unsaturated hydrocarbons burn with a yellow sooty flame.","qno":14,"q":14,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Give a test that can be used to differentiate between saturated and unsaturated hydrocarbons.","hi":"","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q14","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-04-q15","cls":10,"subject":"science","board":"cbse","ans":"Most dirt is oily in nature and insoluble in water. When soap dissolves in water, its hydrophobic hydrocarbon tails attach to the oily dirt droplet while its hydrophilic ionic heads (–COO⁻Na⁺) face outward into water, forming a micelle trapping the oil at the centre. Mutual ion-ion repulsion keeps micelles dispersed as an emulsion; on agitation and rinsing with water, the trapped oily dirt is washed away.","qno":15,"q":15,"ansLetter":null,"opts":null,"ch":4,"chapter":"Carbon and its Compounds","en":"Explain the mechanism of the cleaning action of soaps.","hi":"","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Ch 4 Exercise Q15","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q01","cls":10,"subject":"science","board":"cbse","ans":"excretion.","qno":1,"ansLetter":"B","opts":[{"en":"nutrition.","hi":""},{"en":"excretion.","hi":""},{"en":"respiration.","hi":""},{"en":"transportation.","hi":""}],"ch":5,"chapter":"Life Processes","en":"The kidneys in human beings are a part of the system for","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-05-q02","cls":10,"subject":"science","board":"cbse","ans":"transport of water.","qno":2,"ansLetter":"A","opts":[{"en":"transport of water.","hi":""},{"en":"transport of amino acids.","hi":""},{"en":"transport of food.","hi":""},{"en":"transport of oxygen.","hi":""}],"ch":5,"chapter":"Life Processes","en":"The xylem in plants are responsible for","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-05-q03","cls":10,"subject":"science","board":"cbse","ans":"all of the above.","qno":3,"ansLetter":"D","opts":[{"en":"carbon dioxide and water.","hi":""},{"en":"sunlight.","hi":""},{"en":"chlorophyll.","hi":""},{"en":"all of the above.","hi":""}],"ch":5,"chapter":"Life Processes","en":"The autotrophic mode of nutrition requires","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-05-q04","cls":10,"subject":"science","board":"cbse","ans":"mitochondria.","qno":4,"ansLetter":"C","opts":[{"en":"cytoplasm.","hi":""},{"en":"chloroplast.","hi":""},{"en":"mitochondria.","hi":""},{"en":"nucleus.","hi":""}],"ch":5,"chapter":"Life Processes","en":"The breakdown of pyruvate to give carbon dioxide, water and energy takes place in","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-05-q05","cls":10,"subject":"science","board":"cbse","ans":"Fats are digested in the small intestine. Bile juice from the liver makes the medium alkaline and emulsifies large fat globules into tiny droplets (increasing surface area). Then the enzyme lipase (from pancreatic and intestinal juice) breaks down emulsified fats into fatty acids and glycerol.","qno":5,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"How are fats digested in our bodies? Where does this process take place?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q06","cls":10,"subject":"science","board":"cbse","ans":"Saliva moistens and softens food for easy chewing and swallowing, and contains the enzyme salivary amylase (ptyalin) which breaks down complex starch molecules into simpler sugar (maltose).","qno":6,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"What is the role of saliva in the digestion of food?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q07","cls":10,"subject":"science","board":"cbse","ans":"Necessary conditions for autotrophic nutrition (photosynthesis): carbon dioxide (CO₂), water (H₂O), sunlight and chlorophyll. Its by-products are oxygen (O₂) and water (along with glucose synthesised as food): 6CO₂ + 12H₂O --(Sunlight, Chlorophyll)--> C₆H₁₂O₆ + 6O₂ + 6H₂O.","qno":7,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"What are the necessary conditions for autotrophic nutrition and what are its by-products?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q08","cls":10,"subject":"science","board":"cbse","ans":"Aerobic respiration occurs in presence of O₂ (cytoplasm + mitochondria), completely oxidises glucose to CO₂ and H₂O, and yields large energy (38/36 ATP). Anaerobic respiration occurs in absence of O₂ (cytoplasm only), incompletely breaks glucose into ethanol + CO₂ (in yeast) or lactic acid (in muscles), and yields very little energy (2 ATP). Anaerobic organisms: Yeast and certain anaerobic bacteria.","qno":8,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"What are the differences between aerobic and anaerobic respiration? Name some organisms that use the anaerobic mode of respiration.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q09","cls":10,"subject":"science","board":"cbse","ans":"Lungs contain millions of tiny balloon-like alveoli providing an enormous surface area (~80 m²); their walls are one-cell thick (squamous epithelium) for rapid diffusion, moist, and richly supplied with an extensive network of blood capillaries.","qno":9,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"How are the alveoli designed to maximise the exchange of gases?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q10","cls":10,"subject":"science","board":"cbse","ans":"Haemoglobin is the respiratory pigment in RBCs that transports oxygen from the lungs to all body tissues. Its deficiency (anaemia) reduces the oxygen-carrying capacity of blood, leading to lower cellular energy production, fatigue, breathlessness, weakness and pale skin.","qno":10,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"What would be the consequences of a deficiency of haemoglobin in our bodies?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q11","cls":10,"subject":"science","board":"cbse","ans":"In human double circulation, blood passes through the heart twice in one complete cycle: (1) Pulmonary circulation (heart → lungs → heart for oxygenation) and (2) Systemic circulation (heart → body organs → heart to supply O₂). It is necessary to prevent mixing of oxygenated and deoxygenated blood, ensuring highly efficient O₂ supply to meet the high energy needs of warm-blooded humans (maintaining constant body temperature).","qno":11,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"Describe double circulation of blood in human beings. Why is it necessary?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q12","cls":10,"subject":"science","board":"cbse","ans":"1. Xylem transports water and dissolved minerals; phloem transports prepared food (sucrose), amino acids and hormones.\n2. Xylem flow is unidirectional (roots upward to shoots); phloem translocation is bidirectional (upward and downward).\n3. Xylem relies mainly on physical forces (root pressure and transpiration pull) without ATP; phloem uses active transport requiring energy (ATP).","qno":12,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"What are the differences between the transport of materials in xylem and phloem?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-05-q13","cls":10,"subject":"science","board":"cbse","ans":"Alveoli (functional units of lungs) are thin-walled balloon-like air sacs surrounded by capillaries; they exchange O₂ and CO₂ between inhaled air and blood by diffusion. Nephrons (functional units of kidneys) are tubular units with Bowman’s capsule (containing glomerulus capillaries) and coiled renal tubule; they filter nitrogenous wastes (urea, uric acid) from blood and selectively reabsorb glucose, amino acids, salts and water to form urine. Both possess huge numbers, vast surface area and dense capillary networks.","qno":13,"ansLetter":null,"opts":null,"ch":5,"chapter":"Life Processes","en":"Compare the functioning of alveoli in the lungs and nephrons in the kidneys with respect to their structure and functioning.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 5, Exercise","fig":null,"q":13,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q01","cls":10,"subject":"science","board":"cbse","ans":"Cytokinin.","qno":1,"ansLetter":"D","opts":[{"en":"Insulin","hi":""},{"en":"Thyroxin","hi":""},{"en":"Oestrogen","hi":""},{"en":"Cytokinin.","hi":""}],"ch":6,"chapter":"Control and Coordination","en":"Which of the following is a plant hormone?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-06-q02","cls":10,"subject":"science","board":"cbse","ans":"synapse.","qno":2,"ansLetter":"B","opts":[{"en":"dendrite.","hi":""},{"en":"synapse.","hi":""},{"en":"axon.","hi":""},{"en":"impulse.","hi":""}],"ch":6,"chapter":"Control and Coordination","en":"The gap between two neurons is called a","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-06-q03","cls":10,"subject":"science","board":"cbse","ans":"all of the above.","qno":3,"ansLetter":"D","opts":[{"en":"thinking.","hi":""},{"en":"regulating the heart beat.","hi":""},{"en":"balancing the body.","hi":""},{"en":"all of the above.","hi":""}],"ch":6,"chapter":"Control and Coordination","en":"The brain is responsible for","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-06-q04","cls":10,"subject":"science","board":"cbse","ans":"Receptors are specialised cells in sense organs that detect environmental stimuli (e.g., gustatory for taste, olfactory for smell, photoreceptors for light, thermoreceptors for heat) and generate nerve impulses. If receptors fail (e.g., blocked nose during a cold, damaged skin thermoreceptors), the body cannot sense spoiled food, gas leaks or hot objects, risking injury or harm.","qno":4,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"What is the function of receptors in our body? Think of situations where receptors do not work properly. What problems are likely to arise?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q05","cls":10,"subject":"science","board":"cbse","ans":"A neuron consists of: (1) Dendrites — branched projections receiving information; (2) Cell body (cyton) — containing nucleus and cytoplasm; (3) Axon — long fibre conducting electrical nerve impulses away from the cell body; and (4) Nerve endings — releasing neurotransmitters across the synapse to the next neuron, muscle or gland, enabling rapid signal transmission.","qno":5,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"Draw the structure of a neuron and explain its function.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q06","cls":10,"subject":"science","board":"cbse","ans":"Phototropism is directional growth in response to light. When light falls on one side of a plant shoot, the hormone auxin (synthesised at the shoot tip) diffuses towards the shaded side. Higher auxin concentration stimulates cells on the shaded side to elongate more than those on the lit side, causing the shoot to bend towards light.","qno":6,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"How does phototropism occur in plants?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q07","cls":10,"subject":"science","board":"cbse","ans":"In a spinal cord injury: (1) Reflex actions mediated by the spinal cord are disrupted; and (2) Both sensory impulses travelling from body receptors to the brain and motor impulses travelling from the brain to muscles/effectors below the injury site are disrupted.","qno":7,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"Which signals will get disrupted in case of a spinal cord injury?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q08","cls":10,"subject":"science","board":"cbse","ans":"Plants lack a nervous system and coordinate using chemical messengers called plant hormones (phytohormones), synthesised in one region and diffusing to target sites: Auxins (cell elongation, tropism), Gibberellins (stem growth), Cytokinins (cell division), and Abscisic acid (growth inhibitor, wilting of leaves, stomatal closure).","qno":8,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"How does chemical coordination occur in plants?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q09","cls":10,"subject":"science","board":"cbse","ans":"Multicellular organisms have specialised organs and tissues that must work together in an integrated manner, and must respond accurately and promptly to environmental changes (stimuli) for protection, homeostasis, growth and survival — requiring nervous and hormonal control and coordination.","qno":9,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"What is the need for a system of control and coordination in an organism?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q10","cls":10,"subject":"science","board":"cbse","ans":"Involuntary actions are automatic ongoing internal processes (like heartbeat, breathing, peristalsis, blood pressure) controlled mainly by the mid-brain and hind-brain (medulla) without an external emergency stimulus. Reflex actions are sudden, rapid, automatic responses to a specific external stimulus (like pulling hand away from a hot object) mediated directly by the spinal cord via a reflex arc.","qno":10,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"How are involuntary actions and reflex actions different from each other?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q11","cls":10,"subject":"science","board":"cbse","ans":"Nervous mechanism sends electrical impulses along neurons (with neurotransmitters at synapses): very fast, highly localised (reaches only innervated cells), and short-lived. Hormonal (endocrine) mechanism secretes hormones into blood: slower, widespread (reaches all target cells throughout the body), and longer-lasting/persistent. Both work together via feedback mechanisms.","qno":11,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"Compare and contrast nervous and hormonal mechanisms for control and coordination in animals.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-06-q12","cls":10,"subject":"science","board":"cbse","ans":"Movement in a sensitive plant (Mimosa pudica) is a nastic response with no nerves or muscles: plant cells change shape by rapidly altering their water content (turgor pressure), causing leaves to fold. Movement in our legs is voluntary, controlled by brain and motor neurons, and occurs when muscle cells shorten/change shape using specialised contractile proteins (actin and myosin).","qno":12,"ansLetter":null,"opts":null,"ch":6,"chapter":"Control and Coordination","en":"What is the difference between the manner in which movement takes place in a sensitive plant and the movement in our legs?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 6, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q01","cls":10,"subject":"science","board":"cbse","ans":"Yeast.","qno":1,"ansLetter":"B","opts":[{"en":"Amoeba.","hi":""},{"en":"Yeast.","hi":""},{"en":"Plasmodium.","hi":""},{"en":"Leishmania.","hi":""}],"ch":7,"chapter":"How do Organisms Reproduce?","en":"Asexual reproduction takes place through budding in","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-07-q02","cls":10,"subject":"science","board":"cbse","ans":"Vas deferens","qno":2,"ansLetter":"C","opts":[{"en":"Ovary","hi":""},{"en":"Uterus","hi":""},{"en":"Vas deferens","hi":""},{"en":"Fallopian tube","hi":""}],"ch":7,"chapter":"How do Organisms Reproduce?","en":"Which of the following is not a part of the female reproductive system in human beings?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-07-q03","cls":10,"subject":"science","board":"cbse","ans":"pollen grains.","qno":3,"ansLetter":"D","opts":[{"en":"sepals.","hi":""},{"en":"ovules.","hi":""},{"en":"pistil.","hi":""},{"en":"pollen grains.","hi":""}],"ch":7,"chapter":"How do Organisms Reproduce?","en":"The anther contains","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-07-q04","cls":10,"subject":"science","board":"cbse","ans":"Sexual reproduction combines DNA from two different individuals, generating greater genetic variation in offspring. These variations increase adaptability to changing environments, improve disease resistance, and ensure long-term survival and evolution of the species, unlike asexual reproduction which produces near-identical clones.","qno":4,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"What are the advantages of sexual reproduction over asexual reproduction?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q05","cls":10,"subject":"science","board":"cbse","ans":"The testes perform two main functions in human males: (1) Production of male germ-cells (sperms) for reproduction; and (2) Secretion of the male sex hormone testosterone, which regulates sperm formation and brings about secondary sexual characteristics at puberty.","qno":5,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"What are the functions performed by the testis in human beings?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q06","cls":10,"subject":"science","board":"cbse","ans":"Every month the ovary releases one egg and the uterus prepares a thick, spongy, blood-rich lining (endometrium) to nourish a potential embryo. If the egg is not fertilised, this lining is no longer needed and breaks down slowly, exiting through the vagina as blood and mucous — called menstruation.","qno":6,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"Why does menstruation occur?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q07","cls":10,"subject":"science","board":"cbse","ans":"A longitudinal section (L.S.) of a bisexual flower shows four whorls on the receptacle: (1) Sepals (calyx, green protective outer whorl); (2) Petals (corolla, coloured to attract pollinators); (3) Stamens (male part — anther bearing pollen grains + filament); and (4) Pistil/Carpel (female part — sticky stigma at top, tubular style, and swollen basal ovary containing ovules with female germ-cells).","qno":7,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"Draw a labelled diagram of the longitudinal section of a flower.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q08","cls":10,"subject":"science","board":"cbse","ans":"1. Mechanical barrier methods: Condoms or cervical caps prevent sperm from reaching the egg (condoms also protect against STDs).\n2. Chemical/hormonal methods: Oral contraceptive pills alter hormonal balance to prevent ovulation.\n3. Intrauterine Contraceptive Devices (IUCDs): Copper-T or loop placed in the uterus prevents pregnancy.\n4. Surgical (permanent) methods: Vasectomy (blocking vas deferens in males) and Tubectomy (blocking fallopian tubes in females).","qno":8,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"What are the different methods of contraception?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q09","cls":10,"subject":"science","board":"cbse","ans":"Unicellular organisms consist of a single cell and reproduce mainly by simple asexual methods such as binary fission (Amoeba), multiple fission (Plasmodium) or budding (Yeast). Multicellular organisms have differentiated tissues and specialised reproductive organs, so cell-by-cell division cannot work; they reproduce via complex methods such as spore formation, vegetative propagation or sexual reproduction involving gametes.","qno":9,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"How are the modes for reproduction different in unicellular and multicellular organisms?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q10","cls":10,"subject":"science","board":"cbse","ans":"Reproduction creates new individuals carrying the species’ DNA body design to replace organisms lost to ageing, predation and death, maintaining population numbers. Additionally, DNA variations generated during reproduction allow some individuals to survive drastic environmental changes, preventing extinction.","qno":10,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"How does reproduction help in providing stability to populations of species?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-07-q11","cls":10,"subject":"science","board":"cbse","ans":"1. Preventing unwanted or frequent pregnancies and spacing births.\n2. Protecting maternal and child health.\n3. Controlling population size and improving family standard of living.\n4. Preventing transmission of sexually transmitted diseases (STDs) such as HIV-AIDS, syphilis and gonorrhoea (via barrier methods like condoms).","qno":11,"ansLetter":null,"opts":null,"ch":7,"chapter":"How do Organisms Reproduce?","en":"What could be the reasons for adopting contraceptive methods?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 7, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-08-q01","cls":10,"subject":"science","board":"cbse","ans":"Mendel crossed pure tall (TT) pea plants with pure dwarf (tt) plants. All F₁ progeny (Tt) were tall — no dwarf or medium plants appeared, showing tallness (T) is dominant. On self-pollinating F₁ plants, F₂ progeny produced tall and dwarf plants in a 3:1 phenotypic ratio (1 TT : 2 Tt : 1 tt), proving the dwarf trait (t) was recessive (present in F₁ but expressed only when homozygous tt).","qno":1,"ansLetter":null,"opts":null,"ch":8,"chapter":"Heredity","en":"How do Mendel's experiments show that traits may be dominant or recessive?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 8, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-08-q02","cls":10,"subject":"science","board":"cbse","ans":"In a dihybrid cross between pea plants with round-yellow seeds (RRYY) and wrinkled-green seeds (rryy), all F₁ seeds were round-yellow (RrYy). On selfing F₁, the F₂ generation showed a 9:3:3:1 ratio — round-yellow (9), round-green (3), wrinkled-yellow (3), wrinkled-green (1). The appearance of two new non-parental combinations (round-green and wrinkled-yellow) proves seed shape and seed colour assort independently.","qno":2,"ansLetter":null,"opts":null,"ch":8,"chapter":"Heredity","en":"How do Mendel's experiments show that traits are inherited independently?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 8, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-08-q03","cls":10,"subject":"science","board":"cbse","ans":"No, this information alone is not sufficient. Case 1: If A is dominant, a heterozygous father (Iᴬi) and mother (ii) can produce a daughter with blood group O (ii). Case 2: If O were dominant, a father (aa) and heterozygous mother (Oo) could also produce a daughter with group O (Oo). Since both hypotheses explain the child’s blood group, dominance cannot be deduced from this single cross alone.","qno":3,"ansLetter":null,"opts":null,"ch":8,"chapter":"Heredity","en":"A man with blood group A marries a woman with blood group O and their daughter has blood group O. Is this information enough to tell you which of the traits - blood group A or O - is dominant? Why or why not?","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 8, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-08-q04","cls":10,"subject":"science","board":"cbse","ans":"Humans have 23 pairs of chromosomes: 22 autosome pairs and 1 pair of sex chromosomes — XX in females and XY in males. All eggs carry an X chromosome, while half the sperms carry X and half carry Y. If an X-bearing sperm fertilises the egg, the zygote is XX (girl); if a Y-bearing sperm fertilises the egg, the zygote is XY (boy). Thus sex is determined by the chromosome inherited from the father (50:50 chance).","qno":4,"ansLetter":null,"opts":null,"ch":8,"chapter":"Heredity","en":"How is the sex of the child determined in human beings?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 8, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q01","cls":10,"subject":"science","board":"cbse","ans":"Clay","qno":1,"ansLetter":"D","opts":[{"en":"Water","hi":""},{"en":"Glass","hi":""},{"en":"Plastic","hi":""},{"en":"Clay","hi":""}],"ch":9,"chapter":"Light – Reflection and Refraction","en":"Which one of the following materials cannot be used to make a lens?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-09-q02","cls":10,"subject":"science","board":"cbse","ans":"Between the pole of the mirror and its principal focus.","qno":2,"ansLetter":"D","opts":[{"en":"Between the principal focus and the centre of curvature","hi":""},{"en":"At the centre of curvature","hi":""},{"en":"Beyond the centre of curvature","hi":""},{"en":"Between the pole of the mirror and its principal focus.","hi":""}],"ch":9,"chapter":"Light – Reflection and Refraction","en":"The image formed by a concave mirror is observed to be virtual, erect and larger than the object. Where should be the position of the object?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-09-q03","cls":10,"subject":"science","board":"cbse","ans":"At twice the focal length","qno":3,"ansLetter":"B","opts":[{"en":"At the principal focus of the lens","hi":""},{"en":"At twice the focal length","hi":""},{"en":"At infinity","hi":""},{"en":"Between the optical centre of the lens and its principal focus.","hi":""}],"ch":9,"chapter":"Light – Reflection and Refraction","en":"Where should an object be placed in front of a convex lens to get a real image of the size of the object?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-09-q04","cls":10,"subject":"science","board":"cbse","ans":"both concave.","qno":4,"ansLetter":"A","opts":[{"en":"both concave.","hi":""},{"en":"both convex.","hi":""},{"en":"the mirror is concave and the lens is convex.","hi":""},{"en":"the mirror is convex, but the lens is concave.","hi":""}],"ch":9,"chapter":"Light – Reflection and Refraction","en":"A spherical mirror and a thin spherical lens have each a focal length of –15 cm. The mirror and the lens are likely to be","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-09-q05","cls":10,"subject":"science","board":"cbse","ans":"either plane or convex.","qno":5,"ansLetter":"D","opts":[{"en":"only plane.","hi":""},{"en":"only concave.","hi":""},{"en":"only convex.","hi":""},{"en":"either plane or convex.","hi":""}],"ch":9,"chapter":"Light – Reflection and Refraction","en":"No matter how far you stand from a mirror, your image appears erect. The mirror is likely to be","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-09-q06","cls":10,"subject":"science","board":"cbse","ans":"A convex lens of focal length 5 cm.","qno":6,"ansLetter":"C","opts":[{"en":"A convex lens of focal length 50 cm.","hi":""},{"en":"A concave lens of focal length 50 cm.","hi":""},{"en":"A convex lens of focal length 5 cm.","hi":""},{"en":"A concave lens of focal length 5 cm.","hi":""}],"ch":9,"chapter":"Light – Reflection and Refraction","en":"Which of the following lenses would you prefer to use while reading small letters found in a dictionary?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-09-q07","cls":10,"subject":"science","board":"cbse","ans":"Distance less than 15 cm; virtual; Enlarged.","qno":7,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"We wish to obtain an erect image of an object, using a concave mirror of focal length 15 cm. What should be the range of distance of the object from the mirror? What is the nature of the image? Is the image larger or smaller than the object? Draw a ray diagram to show the image formation in this case.","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q08","cls":10,"subject":"science","board":"cbse","ans":"(a) Headlights of a car: Concave mirror — the bulb is placed at the principal focus so reflected rays form a powerful parallel beam of light.\n(b) Side/rear-view mirror of a vehicle: Convex mirror — it always forms an erect, diminished image and gives a much wider field of view of traffic behind.\n(c) Solar furnace: Large concave mirror — it converges parallel sunrays to a sharp point at its focus, producing intense heat.","qno":8,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"Name the type of mirror used in the following situations:\n(a) Headlights of a car.\n(b) Side/rear-view mirror of a vehicle.\n(c) Solar furnace.\nSupport your answer with reason.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q09","cls":10,"subject":"science","board":"cbse","ans":"Yes","qno":9,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"One-half of a convex lens is covered with a black paper. Will this lens produce a complete image of the object? Verify your answer experimentally. Explain your observations.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q10","cls":10,"subject":"science","board":"cbse","ans":"16.7 cm from the lens on the other side; 3.3 cm, reduced; real, inverted.","qno":10,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"An object 5 cm in length is held 25 cm away from a converging lens of focal length 10 cm. Draw the ray diagram and find the position, size and the nature of the image formed.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q11","cls":10,"subject":"science","board":"cbse","ans":"30 cm","qno":11,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"A concave lens of focal length 15 cm forms an image 10 cm from the lens. How far is the object placed from the lens? Draw the ray diagram.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q12","cls":10,"subject":"science","board":"cbse","ans":"6.0 cm, behind the mirror; virtual, erect","qno":12,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"An object is placed at a distance of 10 cm from a convex mirror of focal length 15 cm. Find the position and nature of the image.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q13","cls":10,"subject":"science","board":"cbse","ans":"m = 1 indicates that image formed by a plane mirror is of the same size as the object. Further, the positive sign of m indicates that the image is virtual and erect.","qno":13,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"The magnification produced by a plane mirror is +1. What does this mean?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":13,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q14","cls":10,"subject":"science","board":"cbse","ans":"8.6 cm, behind the mirror; virtual, erect; 2.2 cm, reduced.","qno":14,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"An object 5.0 cm in length is placed at a distance of 20 cm in front of a convex mirror of radius of curvature 30 cm. Find the position of the image, its nature and size.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":14,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q15","cls":10,"subject":"science","board":"cbse","ans":"54 cm on the object side; 14 cm, magnified; real, inverted.","qno":15,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"An object of size 7.0 cm is placed at 27 cm in front of a concave mirror of focal length 18 cm. At what distance from the mirror should a screen be placed, so that a sharp focussed image can be obtained? Find the size and the nature of the image.","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":15,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q16","cls":10,"subject":"science","board":"cbse","ans":"–0.50 m; concave lens","qno":16,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"Find the focal length of a lens of power – 2.0 D. What type of lens is this?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":16,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-09-q17","cls":10,"subject":"science","board":"cbse","ans":"+ 0.67 m; converging lens","qno":17,"ansLetter":null,"opts":null,"ch":9,"chapter":"Light – Reflection and Refraction","en":"A doctor has prescribed a corrective lens of power +1.5 D. Find the focal length of the lens. Is the prescribed lens diverging or converging?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 9, Exercise","fig":null,"q":17,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q01","cls":10,"subject":"science","board":"cbse","ans":"accommodation.","qno":1,"ansLetter":"B","opts":[{"en":"presbyopia.","hi":""},{"en":"accommodation.","hi":""},{"en":"near-sightedness.","hi":""},{"en":"far-sightedness.","hi":""}],"ch":10,"chapter":"The Human Eye and the Colourful World","en":"The human eye can focus on objects at different distances by adjusting the focal length of the eye lens. This is due to","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-10-q02","cls":10,"subject":"science","board":"cbse","ans":"retina.","qno":2,"ansLetter":"D","opts":[{"en":"cornea.","hi":""},{"en":"iris.","hi":""},{"en":"pupil.","hi":""},{"en":"retina.","hi":""}],"ch":10,"chapter":"The Human Eye and the Colourful World","en":"The human eye forms the image of an object at its","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-10-q03","cls":10,"subject":"science","board":"cbse","ans":"25 cm.","qno":3,"ansLetter":"C","opts":[{"en":"25 m.","hi":""},{"en":"2.5 cm.","hi":""},{"en":"25 cm.","hi":""},{"en":"2.5 m.","hi":""}],"ch":10,"chapter":"The Human Eye and the Colourful World","en":"The least distance of distinct vision for a young adult with normal vision is about","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-10-q04","cls":10,"subject":"science","board":"cbse","ans":"ciliary muscles.","qno":4,"ansLetter":"C","opts":[{"en":"pupil.","hi":""},{"en":"retina.","hi":""},{"en":"ciliary muscles.","hi":""},{"en":"iris.","hi":""}],"ch":10,"chapter":"The Human Eye and the Colourful World","en":"The change in focal length of an eye lens is caused by the action of the","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-10-q05","cls":10,"subject":"science","board":"cbse","ans":"(i) –0.18 m; (ii) +0.67 m","qno":5,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"A person needs a lens of power –5.5 dioptres for correcting his distant vision. For correcting his near vision he needs a lens of power +1.5 dioptre. What is the focal length of the lens required for correcting (i) distant vision, and (ii) near vision?","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q06","cls":10,"subject":"science","board":"cbse","ans":"Concave lens; –1.25 D","qno":6,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"The far point of a myopic person is 80 cm in front of the eye. What is the nature and power of the lens required to correct the problem?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q07","cls":10,"subject":"science","board":"cbse","ans":"Convex lens; +3.0 D","qno":7,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"Make a diagram to show how hypermetropia is corrected. The near point of a hypermetropic eye is 1 m. What is the power of the lens required to correct this defect? Assume that the near point of the normal eye is 25 cm.","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q08","cls":10,"subject":"science","board":"cbse","ans":"To focus on closer objects, the ciliary muscles contract to make the eye lens thicker and decrease its focal length. However, the focal length of the eye lens cannot be decreased below a certain minimum limit, so objects placed closer than the near point (~25 cm) cannot be focused sharply on the retina and appear blurred.","qno":8,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"Why is a normal eye not able to see clearly the objects placed closer than 25 cm?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q09","cls":10,"subject":"science","board":"cbse","ans":"The image distance in the eye remains unchanged (equal to the fixed distance between the eye lens and the retina). As object distance increases, the ciliary muscles relax to increase the focal length of the eye lens (accommodation) so the image continues to form sharply on the retina.","qno":9,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"What happens to the image distance in the eye when we increase the distance of an object from the eye?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q10","cls":10,"subject":"science","board":"cbse","ans":"Stars are very distant point-sized sources of light. Starlight undergoes continuous atmospheric refraction through layers of air of gradually increasing refractive index. Because the atmosphere’s physical conditions (temperature, density) constantly fluctuate, the apparent position of the star and the amount of starlight entering the eye flicker continuously, making stars twinkle.","qno":10,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"Why do stars twinkle?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q11","cls":10,"subject":"science","board":"cbse","ans":"Planets are much closer to Earth and appear as extended sources — a collection of a large number of point-sized sources of light. Random variations in light entering the eye from individual point sources cancel out and average to zero, so their apparent brightness stays steady and planets do not twinkle.","qno":11,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"Explain why the planets do not twinkle.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-10-q12","cls":10,"subject":"science","board":"cbse","ans":"On Earth, the sky looks blue due to scattering of shorter-wavelength blue sunlight by air molecules and fine particles in the atmosphere. In outer space (at an astronaut’s altitude), there is no atmosphere to scatter sunlight into the astronaut’s eyes, so the sky appears dark/black.","qno":12,"ansLetter":null,"opts":null,"ch":10,"chapter":"The Human Eye and the Colourful World","en":"Why does the sky appear dark instead of blue to an astronaut?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 10, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q01","cls":10,"subject":"science","board":"cbse","ans":"25","qno":1,"ansLetter":"D","opts":[{"en":"1/25","hi":""},{"en":"1/5","hi":""},{"en":"5","hi":""},{"en":"25","hi":""}],"ch":11,"chapter":"Electricity","en":"A piece of wire of resistance R is cut into five equal parts. These parts are then connected in parallel. If the equivalent resistance of this combination is R′, then the ratio R/R′ is –","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-11-q02","cls":10,"subject":"science","board":"cbse","ans":"IR2","qno":2,"ansLetter":"B","opts":[{"en":"I2R","hi":""},{"en":"IR2","hi":""},{"en":"VI","hi":""},{"en":"V2/R","hi":""}],"ch":11,"chapter":"Electricity","en":"Which of the following terms does not represent electrical power in a circuit?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-11-q03","cls":10,"subject":"science","board":"cbse","ans":"25 W","qno":3,"ansLetter":"D","opts":[{"en":"100 W","hi":""},{"en":"75 W","hi":""},{"en":"50 W","hi":""},{"en":"25 W","hi":""}],"ch":11,"chapter":"Electricity","en":"An electric bulb is rated 220 V and 100 W. When it is operated on 110 V, the power consumed will be –","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-11-q04","cls":10,"subject":"science","board":"cbse","ans":"1:4","qno":4,"ansLetter":"C","opts":[{"en":"1:2","hi":""},{"en":"2:1","hi":""},{"en":"1:4","hi":""},{"en":"4:1","hi":""}],"ch":11,"chapter":"Electricity","en":"Two conducting wires of the same material and of equal lengths and equal diameters are first connected in series and then parallel in a circuit across the same potential difference. The ratio of heat produced in series and parallel combinations would be –","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-11-q05","cls":10,"subject":"science","board":"cbse","ans":"Parallel","qno":5,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"How is a voltmeter connected in the circuit to measure the potential difference between two points?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q06","cls":10,"subject":"science","board":"cbse","ans":"122.7 m; ¼ times","qno":6,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"A copper wire has diameter 0.5 mm and resistivity of 1.6 × 10⁻⁸ Ω m. What will be the length of this wire to make its resistance 10 Ω? How much does the resistance change if the diameter is doubled?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q07","cls":10,"subject":"science","board":"cbse","ans":"Plotting V (y-axis) against I (x-axis) gives a straight line passing through the origin (verifying Ohm’s law). Resistance R = slope = ΔV/ΔI. Using individual ratios: 1.6/0.5 = 3.2 Ω, 3.4/1.0 = 3.4 Ω, 6.7/2.0 = 3.35 Ω, 10.2/3.0 = 3.4 Ω, 13.2/4.0 = 3.3 Ω; or slope = (13.2 − 1.6)/(4.0 − 0.5) = 11.6/3.5 ≈ 3.3 Ω. Average resistance R ≈ 3.3 Ω.","qno":7,"q":7,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"The values of current I flowing in a given resistor for the corresponding values of potential difference V across the resistor are given below:\nI (amperes): 0.5, 1.0, 2.0, 3.0, 4.0\nV (volts): 1.6, 3.4, 6.7, 10.2, 13.2\nPlot a graph between V and I and calculate the resistance of that resistor.","hi":"","kind":"short","m":3,"lv":"Standard","src":"NCERT Class 10 Science, Ch 11 Exercise Q7","fig":null,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q08","cls":10,"subject":"science","board":"cbse","ans":"4.8 kΩ","qno":8,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"When a 12 V battery is connected across an unknown resistor, there is a current of 2.5 mA in the circuit. Find the value of the resistance of the resistor.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q09","cls":10,"subject":"science","board":"cbse","ans":"0.67 A","qno":9,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"A battery of 9 V is connected in series with resistors of 0.2 Ω, 0.3 Ω, 0.4 Ω, 0.5 Ω and 12 Ω, respectively. How much current would flow through the 12 Ω resistor?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q10","cls":10,"subject":"science","board":"cbse","ans":"4 resistors","qno":10,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"How many 176 Ω resistors (in parallel) are required to carry 5 A on a 220 V line?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":10,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q11","cls":10,"subject":"science","board":"cbse","ans":"(i) For 9 Ω: Connect two 6 Ω resistors in parallel and connect the third 6 Ω resistor in series with this parallel pair. R_p = (6 × 6)/(6 + 6) = 3 Ω; then R_eq = 6 Ω + 3 Ω = 9 Ω.\n(ii) For 4 Ω: Connect two 6 Ω resistors in series (R_s = 6 + 6 = 12 Ω) and connect the third 6 Ω resistor in parallel across them. 1/R_eq = 1/12 + 1/6 = 3/12 = 1/4 ⇒ R_eq = 4 Ω.","qno":11,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"Show how you would connect three resistors, each of resistance 6 Ω, so that the combination has a resistance of (i) 9 Ω, (ii) 4 Ω.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":11,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q12","cls":10,"subject":"science","board":"cbse","ans":"110 bulbs","qno":12,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"Several electric bulbs designed to be used on a 220 V electric supply line, are rated 10 W. How many lamps can be connected in parallel with each other across the two wires of 220 V line if the maximum allowable current is 5 A?","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":12,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q13","cls":10,"subject":"science","board":"cbse","ans":"9.2 A, 4.6 A, 18.3 A","qno":13,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"A hot plate of an electric oven connected to a 220 V line has two resistance coils A and B, each of 24 Ω resistance, which may be used separately, in series, or in parallel. What are the currents in the three cases?","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":13,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q14","cls":10,"subject":"science","board":"cbse","ans":"(i) Series circuit (6 V with 1 Ω and 2 Ω): R_total = 1 + 2 = 3 Ω; current I = V/R = 6/3 = 2 A. Power in 2 Ω resistor = I²R = (2)² × 2 = 8 W.\n(ii) Parallel circuit (4 V across 12 Ω and 2 Ω): Potential difference across 2 Ω resistor is V = 4 V. Power in 2 Ω resistor = V²/R = (4)²/2 = 16/2 = 8 W.\nConclusion: Both circuits consume the same power (8 W) in the 2 Ω resistor.","qno":14,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"Compare the power used in the 2 Ω resistor in each of the following circuits:\n(i) a 6 V battery in series with 1 Ω and 2 Ω resistors, and\n(ii) a 4 V battery in parallel with 12 Ω and 2 Ω resistors.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":14,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q15","cls":10,"subject":"science","board":"cbse","ans":"0.73 A","qno":15,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"Two lamps, one rated 100 W at 220 V, and the other 60 W at 220 V, are connected in parallel to electric mains supply. What current is drawn from the line if the supply voltage is 220 V?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":15,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q16","cls":10,"subject":"science","board":"cbse","ans":"250 W TV set in 1 hour","qno":16,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"Which uses more energy, a 250 W TV set in 1 hr, or a 1200 W toaster in 10 minutes?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":16,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q17","cls":10,"subject":"science","board":"cbse","ans":"1100 W","qno":17,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"An electric heater of resistance 44 Ω draws 5 A from the service mains for 2 hours. Calculate the rate at which heat is developed in the heater.","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":17,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-11-q18","cls":10,"subject":"science","board":"cbse","ans":"(a) Tungsten has an extremely high melting point (3380 °C) and high resistivity, so it glows white-hot without melting.\n(b) Alloys have higher resistivity than pure constituent metals and do not oxidise (burn) readily at high temperatures.\n(c) In series, if one appliance fails the entire circuit breaks, appliances cannot be switched independently, each gets reduced voltage, and high- and low-power devices cannot draw their required currents.\n(d) Resistance is inversely proportional to area of cross-section (R ∝ 1/A): thicker wires have lower resistance.\n(e) Copper and aluminium have very low electrical resistivity (minimising I²R heat loss) and are ductile and economical.","qno":18,"ansLetter":null,"opts":null,"ch":11,"chapter":"Electricity","en":"Explain the following:\n(a) Why is the tungsten used almost exclusively for filament of electric lamps?\n(b) Why are the conductors of electric heating devices, such as bread-toasters and electric irons, made of an alloy rather than a pure metal?\n(c) Why is the series arrangement not used for domestic circuits?\n(d) How does the resistance of a wire vary with its area of cross-section?\n(e) Why are copper and aluminium wires usually employed for electricity transmission?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 11, Exercise","fig":null,"q":18,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q01","cls":10,"subject":"science","board":"cbse","ans":"The field consists of concentric circles centred on the wire.","qno":1,"ansLetter":"D","opts":[{"en":"The field consists of straight lines perpendicular to the wire.","hi":""},{"en":"The field consists of straight lines parallel to the wire.","hi":""},{"en":"The field consists of radial lines originating from the wire.","hi":""},{"en":"The field consists of concentric circles centred on the wire.","hi":""}],"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"Which of the following correctly describes the magnetic field near a long straight wire?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-12-q02","cls":10,"subject":"science","board":"cbse","ans":"increases heavily.","qno":2,"ansLetter":"C","opts":[{"en":"reduces substantially.","hi":""},{"en":"does not change.","hi":""},{"en":"increases heavily.","hi":""},{"en":"vary continuously.","hi":""}],"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"At the time of short circuit, the current in the circuit","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-12-q03","cls":10,"subject":"science","board":"cbse","ans":"(a) True — Near the centre of a current-carrying circular coil, magnetic field arcs appear as nearly parallel straight lines (uniform field).\n(b) False — Green insulation is used for the earth wire; the live wire usually has red insulation.","qno":3,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"State whether the following statements are true or false:\n(a) The field at the centre of a long circular coil carrying current will be parallel straight lines.\n(b) A wire with a green insulation is usually the live wire of an electric supply.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q04","cls":10,"subject":"science","board":"cbse","ans":"Two methods of producing magnetic fields: (1) Using a permanent magnet (bar magnet, horseshoe magnet); (2) Passing an electric current through a conductor (straight wire, circular loop or solenoid/electromagnet).","qno":4,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"List two methods of producing magnetic fields.","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q05","cls":10,"subject":"science","board":"cbse","ans":"The magnetic force on a current-carrying conductor is largest (maximum) when the direction of electric current is perpendicular (at 90°) to the direction of the magnetic field.","qno":5,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"When is the force experienced by a current–carrying conductor placed in a magnetic field largest?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q06","cls":10,"subject":"science","board":"cbse","ans":"vertically downwards","qno":6,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"Imagine that you are sitting in a chamber with your back to one wall. An electron beam, moving horizontally from back wall towards the front wall, is deflected by a strong magnetic field to your right side. What is the direction of magnetic field?","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q07","cls":10,"subject":"science","board":"cbse","ans":"(i) Maxwell’s right-hand thumb rule.\n(ii) Fleming’s left-hand rule.\n(iii) Fleming’s right-hand rule.","qno":7,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"State the rule to determine the direction of a (i) magnetic field produced around a straight conductor carrying current, (ii) force experienced by a current-carrying straight conductor placed in a magnetic field which is perpendicular to it, and (iii) current induced in a coil due to its rotation in a magnetic field.","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q08","cls":10,"subject":"science","board":"cbse","ans":"An electric short circuit occurs when the live wire and the neutral wire come into direct contact (due to damaged/worn insulation or an appliance fault). Circuit resistance drops almost to zero, causing current to rise abruptly and dangerously.","qno":8,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"When does an electric short circuit occur?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-12-q09","cls":10,"subject":"science","board":"cbse","ans":"The earth wire (green insulation, connected to a metal plate deep in the ground) provides a low-resistance conducting path for leakage current. Earthing metallic-bodied appliances ensures that if live wire touches the metal casing, its potential remains equal to earth potential and leakage current flows safely to ground, protecting the user from severe electric shock.","qno":9,"ansLetter":null,"opts":null,"ch":12,"chapter":"Magnetic Effects of Electric Current","en":"What is the function of an earth wire? Why is it necessary to earth metallic appliances?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 12, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-13-q01","cls":10,"subject":"science","board":"cbse","ans":"(a), (c) and (d) — Grass, flowers, leather, fruit-peels, cake, lime-juice and wood are all biodegradable; plastic in (b) is non-biodegradable.","qno":1,"ansLetter":"A","opts":[{"en":"(a), (c) and (d)","hi":""},{"en":"(a), (b) and (c)","hi":""},{"en":"(b) and (d) only","hi":""},{"en":"(b) only","hi":""}],"ch":13,"chapter":"Our Environment","en":"Which of the following groups contain only biodegradable items?","kind":"mcq","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":1,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-13-q02","cls":10,"subject":"science","board":"cbse","ans":"Grass, goat and human","qno":2,"ansLetter":"B","opts":[{"en":"Grass, wheat and mango","hi":""},{"en":"Grass, goat and human","hi":""},{"en":"Goat, cow and elephant","hi":""},{"en":"Grass, fish and goat","hi":""}],"ch":13,"chapter":"Our Environment","en":"Which of the following constitute a food-chain?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":2,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-13-q03","cls":10,"subject":"science","board":"cbse","ans":"All of the above","qno":3,"ansLetter":"D","opts":[{"en":"Carrying cloth-bags to put purchases in while shopping","hi":""},{"en":"Switching off unnecessary lights and fans","hi":""},{"en":"Walking to school instead of getting your mother to drop you on her scooter","hi":""},{"en":"All of the above","hi":""}],"ch":13,"chapter":"Our Environment","en":"Which of the following are environment-friendly practices?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":3,"keyVerified":true,"sourceType":"ncert-key"},{"id":"sci10-13-q04","cls":10,"subject":"science","board":"cbse","ans":"Killing all organisms in one trophic level disrupts the food chain: organisms in the next higher trophic level will starve and decline due to lack of food, while organisms in the trophic level just below will multiply unchecked, creating severe ecological imbalance.","qno":4,"ansLetter":null,"opts":null,"ch":13,"chapter":"Our Environment","en":"What will happen if we kill all the organisms in one trophic level?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":4,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-13-q05","cls":10,"subject":"science","board":"cbse","ans":"Yes, the impact varies by trophic level — e.g., removing producers collapses the entire ecosystem, while removing top carnivores causes herbivore overpopulation and overgrazing of vegetation. No, organisms of any trophic level cannot be completely removed without damaging the ecosystem because all trophic levels are interdependent.","qno":5,"ansLetter":null,"opts":null,"ch":13,"chapter":"Our Environment","en":"Will the impact of removing all the organisms in a trophic level be different for different trophic levels? Can the organisms of any trophic level be removed without causing any damage to the ecosystem?","kind":"short","m":2,"lv":"Standard","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":5,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-13-q06","cls":10,"subject":"science","board":"cbse","ans":"Biological magnification (biomagnification) is the progressive increase in concentration of non-biodegradable toxic chemicals (such as DDT, pesticides, heavy metals) at successive trophic levels of a food chain. Yes, levels increase up the food chain and are highest at the top trophic level (e.g., human beings and predatory birds).","qno":6,"ansLetter":null,"opts":null,"ch":13,"chapter":"Our Environment","en":"What is biological magnification? Will the levels of this magnification be different at different levels of the ecosystem?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":6,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-13-q07","cls":10,"subject":"science","board":"cbse","ans":"1. Non-biodegradable wastes (plastics, glass, pesticides) persist for centuries, causing land, water and soil pollution.\n2. They clog drains and harm animals that accidentally swallow plastics.\n3. Toxic chemicals leach into groundwater and enter food chains, causing biological magnification and health hazards.","qno":7,"ansLetter":null,"opts":null,"ch":13,"chapter":"Our Environment","en":"What are the problems caused by the non-biodegradable wastes that we generate?","kind":"short","m":1,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":7,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-13-q08","cls":10,"subject":"science","board":"cbse","ans":"No — excessive biodegradable waste still impacts the environment if generated faster than decomposers can break it down: heaps produce foul odours and toxic/greenhouse gases (methane, CO₂), pollute water bodies (eutrophication/oxygen depletion), and act as breeding grounds for flies, mosquitoes and disease-causing microbes.","qno":8,"ansLetter":null,"opts":null,"ch":13,"chapter":"Our Environment","en":"If all the waste we generate is biodegradable, will this have no impact on the environment?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":8,"keyVerified":true,"sourceType":"ai-verified"},{"id":"sci10-13-q09","cls":10,"subject":"science","board":"cbse","ans":"The stratospheric ozone layer (O₃) shields life on Earth from harmful ultraviolet (UV) radiation, which causes skin cancer, cataracts, immune damage and harm to crops/plankton. Steps taken: Under UNEP’s 1987 Montreal Protocol, nations froze CFC production at 1986 levels and mandated CFC-free refrigerators, ACs and aerosols.","qno":9,"ansLetter":null,"opts":null,"ch":13,"chapter":"Our Environment","en":"Why is damage to the ozone layer a cause for concern? What steps are being taken to limit this damage?","kind":"short","m":2,"lv":"Basic","src":"NCERT Class 10 Science, Chapter 13, Exercise","fig":null,"q":9,"keyVerified":true,"sourceType":"ai-verified"}];
  UP.pyq = (UP.pyq || []).concat(UP.science10Q);
})();
